import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"委托、撮合与成交","description":"理解订单为何可能成交多次，以及撤单究竟撤销什么。","frontmatter":{"title":"委托、撮合与成交","description":"理解订单为何可能成交多次，以及撤单究竟撤销什么。"},"headers":[],"relativePath":"fundamentals/orders.md","filePath":"fundamentals/orders.md"}'),d={name:"fundamentals/orders.md"};function s(n,a,i,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<div class="doc-eyebrow">交易所基础知识 / TGEX KNOWLEDGE BASE</div><h1 id="委托、撮合与成交" tabindex="-1">委托、撮合与成交 <a class="header-anchor" href="#委托、撮合与成交" aria-label="Permalink to &quot;委托、撮合与成交&quot;">​</a></h1><div class="doc-lead">理解订单为何可能成交多次，以及撤单究竟撤销什么。</div><h2 id="三个对象" tabindex="-1">三个对象 <a class="header-anchor" href="#三个对象" aria-label="Permalink to &quot;三个对象&quot;">​</a></h2><p>委托表达交易意图，例如以不高于 60,000 的价格买入 0.01 BTC。撮合负责寻找符合条件的对手订单。成交记录描述实际发生的一次交换。</p><p>一个委托可以没有成交，也可以产生多笔成交。撤单只终止未成交部分，已经完成的成交保留。</p><h2 id="状态与数量" tabindex="-1">状态与数量 <a class="header-anchor" href="#状态与数量" aria-label="Permalink to &quot;状态与数量&quot;">​</a></h2><p>原始数量 = 累计成交数量 + 剩余数量。对于已撤销订单，剩余数量不再参与交易，但历史成交仍需要结算。</p><h2 id="盘口、行情与-k-线" tabindex="-1">盘口、行情与 K 线 <a class="header-anchor" href="#盘口、行情与-k-线" aria-label="Permalink to &quot;盘口、行情与 K 线&quot;">​</a></h2><p>盘口描述当前挂单，最新成交描述已经发生的交易，K 线是某个时间区间内成交价格和成交量的聚合。三者更新时间和数据含义不同。</p>',10)])])}const m=e(d,[["render",s]]);export{p as __pageData,m as default};
